#include <stdio.h>
#include <stdlib.h>

// Structure for a node in the linked list
typedef struct Node {
    int data;
    struct Node* next;
} Node;

// Function to create a new node
Node* createNode(int data) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory error\n");
        return NULL;
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Function to insert a node at the end of the linked list
void insertNode(Node** head, int data) {
    Node* newNode = createNode(data);
    if (*head == NULL) {
        *head = newNode;
        return;
    }
    Node* temp = *head;
    while (temp->next != NULL) {
        temp = temp->next;
    }
    temp->next = newNode;
}

// Function to print the linked list
void printList(Node* head) {
    Node* temp = head;
    while (temp != NULL) {
        printf("%d -> ", temp->data);
        temp = temp->next;
    }
    printf("NULL\n");
}

// Function to divide the linked list into even and odd nodes
Node* divideList(Node* head) {
    Node* evenHead = NULL;
    Node* oddHead = NULL;
    Node* evenTail = NULL;
    Node* oddTail = NULL;

    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        temp->next = NULL;

        if (temp->data % 2 == 0) {
            if (evenHead == NULL) {
                evenHead = temp;
                evenTail = temp;
            } else {
                evenTail->next = temp;
                evenTail = temp;
            }
        } else {
            if (oddHead == NULL) {
                oddHead = temp;
                oddTail = temp;
            } else {
                oddTail->next = temp;
                oddTail = temp;
            }
        }
    }

    if (evenHead == NULL) {
        return oddHead;
    }

    evenTail->next = oddHead;
    return evenHead;
}

